import { createHash } from "node:crypto";

/** The only persisted attachment references supported by the checkpoint format. */
export const CHECKPOINT_ATTACHMENT_REF_KINDS = [
  "task-attachment",
  "recovery-instruction",
  "context",
  "external-artifact-ref",
  "ledger-checkpoint",
] as const;

export type CheckpointAttachmentRefKind =
  (typeof CHECKPOINT_ATTACHMENT_REF_KINDS)[number];

export type CheckpointAttachmentRef = {
  kind: CheckpointAttachmentRefKind;
  attachmentRef: string;
  contentHash: string;
  owner: string;
  expiresAt: string | number | Date;
};

export type CheckpointAttachmentBinding = CheckpointAttachmentRef;

export type CheckpointAttachmentRepairStatus =
  | "recovered"
  | "missing-hash"
  | "invalid-hash"
  | "missing-owner"
  | "expired"
  | "conflict"
  | "invalid-ref"
  | "missing-ttl"
  | "invalid-ttl";

export type CheckpointAttachmentRepair = {
  attachmentRef: string;
  kind?: CheckpointAttachmentRefKind;
  contentHash?: string;
  status: CheckpointAttachmentRepairStatus;
  reason: string;
};

export type RecoveredCheckpointAttachment = CheckpointAttachmentRef & {
  status: "recovered";
};

export type CheckpointAttachmentRecoveryResult = {
  recovered: RecoveredCheckpointAttachment[];
  conflicts: CheckpointAttachmentRepair[];
  rejected: CheckpointAttachmentRepair[];
  repairs: CheckpointAttachmentRepair[];
  digest: string;
};

export type RecoverCheckpointAttachmentBindingsOptions = {
  /** Injectable clock for deterministic callers and tests. */
  now?: Date | number;\n};

const SHA256_HEX = /^[a-f0-9]{64}$/i;
const ALLOWED_KINDS = new Set<string>(CHECKPOINT_ATTACHMENT_REF_KINDS);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function nonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function canonicalJson(value: unknown): string {
  if (value === null || typeof value !== "object") {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map(canonicalJson).join(",")}]`;
  }
  const record = value as Record<string, unknown>;
  return `{${Object.keys(record)
    .sort()
    .map((key) => `${JSON.stringify(key)}:${canonicalJson(record[key])}`)
    .join(",")}}`;
}

function sha256(value: string): string {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

function epoch(value: string | number | Date): number | undefined {
  if (value instanceof Date) {
    const result = value.getTime();
    return Number.isFinite(result) ? result : undefined;
  }
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : undefined;
  }
  if (typeof value === "string" && value.trim() !== "") {
    const result = Date.parse(value);
    return Number.isFinite(result) ? result : undefined;
  }
  return undefined;
}

function rawBinding(binding: Record<string, unknown>): {
  kind?: unknown;
  attachmentRef?: unknown;
  contentHash?: unknown;
  owner?: unknown;
  expiresAt?: unknown;
} {
  return {
    kind: binding.kind ?? binding.refKind ?? binding.refType,
    attachmentRef: binding.attachmentRef ?? binding.ref,
    contentHash: binding.contentHash ?? binding.hash,
    owner: binding.owner,
    expiresAt: binding.expiresAt,
  };
}

/**
 * Validates one binding without changing it. The returned state is explicit and
 * can therefore be persisted as a repair record instead of silently dropping
 * malformed input.
 */
export function validateCheckpointAttachmentBinding(
  input: unknown,
  options: RecoverCheckpointAttachmentBindingsOptions = {},
): CheckpointAttachmentRepair | RecoveredCheckpointAttachment {
  if (!isRecord(input)) {
    return {
      attachmentRef: "",
      status: "invalid-ref",
      reason: "binding must be an object",
    };
  }

  const binding = rawBinding(input);
  const attachmentRef = nonEmptyString(binding.attachmentRef)
    ? binding.attachmentRef.trim()
    : "";
  const kind = nonEmptyString(binding.kind) ? binding.kind.trim() : undefined;
  const contentHash = nonEmptyString(binding.contentHash)
    ? binding.contentHash.trim()
    : undefined;
  const owner = nonEmptyString(binding.owner) ? binding.owner.trim() : undefined;
  const expiresAt = epoch(binding.expiresAt as string | number | Date | undefined);
  const now = epoch(options.now ?? new Date()) ?? Date.now();

  if (!attachmentRef || !kind || !ALLOWED_KINDS.has(kind)) {
    return {
      attachmentRef,
      kind: kind as CheckpointAttachmentRefKind | undefined,
      contentHash,
      status: "invalid-ref",
      reason: "attachmentRef and an allowed reference kind are required",
    };
  }
  if (contentHash === undefined) {
    return {
      attachmentRef,
      kind: kind as CheckpointAttachmentRefKind,
      status: "missing-hash",
      reason: "contentHash is required",
    };
  }
  if (!SHA256_HEX.test(contentHash)) {
    return {
      attachmentRef,
      kind: kind as CheckpointAttachmentRefKind,
      contentHash,
      status: "invalid-hash",
      reason: "contentHash must be a SHA-256 hexadecimal digest",
    };
  }
  if (owner === undefined) {
    return {
      attachmentRef,
      kind: kind as CheckpointAttachmentRefKind,
      contentHash,
      status: "missing-owner",
      reason: "owner is required",
    };
  }
  if (binding.expiresAt === undefined || binding.expiresAt === null || binding.expiresAt === "") {
    return {
      attachmentRef,
      kind: kind as CheckpointAttachmentRefKind,
      contentHash,
      owner,
      status: "missing-ttl",
      reason: "expiresAt is required",
    };
  }
  if (expiresAt === undefined) {
    return {
      attachmentRef,
      kind: kind as CheckpointAttachmentRefKind,
      contentHash,
      owner,
      status: "invalid-ttl",
      reason: "expiresAt must be a valid date or timestamp",
    };
  }
  if (expiresAt <= now) {
    return {
      attachmentRef,
      kind: kind as CheckpointAttachmentRefKind,
      contentHash,
      owner,
      status: "expired",
      reason: "attachment TTL has expired",
    };
  }

  return {
    attachmentRef,
    kind: kind as CheckpointAttachmentRefKind,
    contentHash: contentHash.toLowerCase(),
    owner,
    expiresAt: new Date(expiresAt).toISOString(),
    status: "recovered",
  };
}

function readBindings(input: unknown): unknown[] {
  if (Array.isArray(input)) {
    return input;
  }
  if (isRecord(input) && Array.isArray(input.bindings)) {
    return input.bindings;
  }
  if (isRecord(input) && Array.isArray(input.attachments)) {
    return input.attachments;
  }
  return [];
}

function compareRecovered(
  left: RecoveredCheckpointAttachment,
  right: RecoveredCheckpointAttachment,
): number {
  return (
    left.attachmentRef.localeCompare(right.attachmentRef) ||
    left.kind.localeCompare(right.kind) ||
    left.contentHash.localeCompare(right.contentHash) ||
    left.owner.localeCompare(right.owner) ||
    left.expiresAt.localeCompare(right.expiresAt)
  );
}

function compareRepair(left: CheckpointAttachmentRepair, right: CheckpointAttachmentRepair): number {
  return (
    left.attachmentRef.localeCompare(right.attachmentRef) ||
    left.status.localeCompare(right.status) ||
    left.reason.localeCompare(right.reason) ||
    (left.contentHash ?? "").localeCompare(right.contentHash ?? "")
  );
}

/**
 * Pure checkpoint recovery. It validates and de-duplicates references, records
 * explicit repair states, and never mutates its input or executes attachment
 * side effects.
 */
export function recoverCheckpointAttachmentBindings(
  input: unknown,
  options: RecoverCheckpointAttachmentBindingsOptions = {},
): CheckpointAttachmentRecoveryResult {
  const bindings = readBindings(input);
  const recovered: RecoveredCheckpointAttachment[] = [];
  const rejected: CheckpointAttachmentRepair[] = [];
  const conflicts: CheckpointAttachmentRepair[] = [];
  const byRef = new Map<string, RecoveredCheckpointAttachment>();

  for (const candidate of bindings) {
    const state = validateCheckpointAttachmentBinding(candidate, options);
    if (state.status !== "recovered") {
      rejected.push(state);
      continue;
    }

    const first = byRef.get(state.attachmentRef);
    if (!first) {
      byRef.set(state.attachmentRef, state);
      recovered.push(state);
      continue;
    }

    if (first.contentHash.toLowerCase() === state.contentHash.toLowerCase()) {
      // Same ref and hash is an idempotent duplicate.
      continue;
    }

    conflicts.push({
      attachmentRef: state.attachmentRef,
      kind: state.kind,
      contentHash: state.contentHash,
      status: "conflict",
      reason: "attachmentRef is already bound to a different content hash",
    });
  }

  recovered.sort(compareRecovered);
  rejected.sort(compareRepair);
  conflicts.sort(compareRepair);
  const repairs = [...rejected, ...conflicts].sort(compareRepair);
  const digest = sha256(
    canonicalJson({
      recovered: recovered.map(({ status: _status, ...value }) => value),
      conflicts,
      rejected,
    }),
  );

  return { recovered, conflicts, rejected, repairs, digest };
}

export const recoverCheckpointAttachments = recoverCheckpointAttachmentBindings;

export function checkpointAttachmentBindingDigest(
  result: Pick<CheckpointAttachmentRecoveryResult, "recovered" | "conflicts" | "rejected">,
): string {
  return sha256(
    canonicalJson({
      recovered: result.recovered.map(({ status: _status, ...value }) => value),
      conflicts: result.conflicts,
      rejected: result.rejected,
    }),
  );
}

