  /** Injectable clock for deterministic callers and tests. */
  now?: Date | number;\n};

const SHA256_HEX = /^[a-f0-9]{64}$/i;
const ALLOWED_KINDS = new Set<string>(CHECKPOINT_ATTACHMENT_REF_KINDS);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function nonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function canonicalJson(value: unknown): string {
  if (value === null || typeof value !== "object") {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map(canonicalJson).join(",")}]`;
  }
  const record = value as Record<string, unknown>;
  return `{${Object.keys(record)
    .sort()
    .map((key) => `${JSON.stringify(key)}:${canonicalJson(record[key])}`)
    .join(",")}}`;
}

function sha256(value: string): string {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

function epoch(value: string | number | Date): number | undefined {
  if (value instanceof Date) {
    const result = value.getTime();
    return Number.isFinite(result) ? result : undefined;
  }
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : undefined;
  }
  if (typeof value === "string" && value.trim() !== "") {
    const result = Date.parse(value);
    return Number.isFinite(result) ? result : undefined;
  }
  return undefined;
}

function rawBinding(binding: Record<string, unknown>): {
  kind?: unknown;
  attachmentRef?: unknown;
  contentHash?: unknown;
  owner?: unknown;
  expiresAt?: unknown;
} {
  return {
    kind: binding.kind ?? binding.refKind ?? binding.refType,
    attachmentRef: binding.attachmentRef ?? binding.ref,
    contentHash: binding.contentHash ?? binding.hash,
    owner: binding.owner,
    expiresAt: binding.expiresAt,
  };
}

/**
 * Validates one binding without changing it. The returned state is explicit and
 * can therefore be persisted as a repair record instead of silently dropping
 * malformed input.
 */
export function validateCheckpointAttachmentBinding(
  input: unknown,
  options: RecoverCheckpointAttachmentBindingsOptions = {},
): CheckpointAttachmentRepair | RecoveredCheckpointAttachment {
  if (!isRecord(input)) {
    return {
      attachmentRef: "",
      status: "invalid-ref",
      reason: "binding must be an object",
    };
  }

  const binding = rawBinding(input);
  const attachmentRef = nonEmptyString(binding.attachmentRef)
    ? binding.attachmentRef.trim()
    : "";
  const kind = nonEmptyString(binding.kind) ? binding.kind.trim() : undefined;
  const contentHash = nonEmptyString(binding.contentHash)
    ? binding.contentHash.trim()
    : undefined;
  const owner = nonEmptyString(binding.owner) ? binding.owner.trim() : undefined;
  const expiresAt = epoch(binding.expiresAt as string | number | Date | undefined);
  const now = epoch(options.now ?? new Date()) ?? Date.now();

